export const getIncomeByDate = (date: string): number => {
  const income = dailyIncomes.find((i) => i.data === date);
  return income ? income.valor : 0;
};

export const getIncomeByMonth = (month: number): number => {
  return dailyIncomes
    .filter((i) => {
      const [, m] = i.data.split("/").map(Number);
      return m - 1 === month;
    })
    .reduce((sum, i) => sum + i.valor, 0);
};

