export const formatCurrency = (value: number): string =>
  new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(value);

export const parseDate = (dateStr: string): Date => {
  const [day, month, year] = dateStr.split("/").map(Number);
  return new Date(year, month - 1, day);
};

export const getTransactionsByDate = (date: string) =>
  transactions.filter((t) => t.data === date);

export const getDailyTotals = () => {
  const map = new Map<string, number>();
  transactions.filter(t => t.tipo === "saida").forEach((t) => {
    map.set(t.data, (map.get(t.data) || 0) + t.valor);
  });
  return map;
};

export const getCategoryTotals = () => {
  const map = new Map<CategoryCode, number>();
  transactions.filter(t => t.tipo === "saida").forEach((t) => {
    map.set(t.categoria, (map.get(t.categoria) || 0) + t.valor);
  });
  return map;
};

export const totalExpenses = transactions.filter(t => t.tipo === "saida").reduce((sum, t) => sum + t.valor, 0);
export const totalIncome = dailyIncomes.reduce((sum, i) => sum + i.valor, 0);
